def kth_smallest_matrix_sum(mat, k):
 import heapq
 sums=[0]
 for row in mat:
  heap=[]
  for total in sums:
   for value in row:heapq.heappush(heap,total+value)
  sums=[heapq.heappop(heap) for _ in range(min(k,len(heap)))]
 return sums[k-1]

